<?php
namespace App\Http\Controllers;
use App\Models\AdvanceSalary;use App\Models\HrPayrollPreflightRun;use Illuminate\Support\Facades\DB;
class HrRoleWorklistController extends AccountBaseController{public function finance(){abort_403(user()->permission('view_payroll')==='none');$company=user()->company_id;$this->preflights=HrPayrollPreflightRun::where('company_id',$company)->latest()->take(6)->get();$this->pendingAdvances=AdvanceSalary::where('status','pending')->whereHas('employee',fn($q)=>$q->where('company_id',$company))->count();return view('hr-role-worklists.finance',$this->data);}public function it(){abort_403(!in_array('admin',user_roles()));$this->tasks=DB::table('hr_offboarding_tasks')->join('hr_offboarding_cases','hr_offboarding_cases.id','=','hr_offboarding_tasks.case_id')->join('users','users.id','=','hr_offboarding_cases.employee_id')->where('hr_offboarding_cases.company_id',user()->company_id)->where('hr_offboarding_tasks.status','pending')->where('hr_offboarding_tasks.title','like','%DMS/DOBS access%')->select('hr_offboarding_tasks.*','users.name as employee_name')->get();return view('hr-role-worklists.it',$this->data);}}
